// server/utils/mediaConverter.ts
import sharp from "sharp";
async function convertImageToWebP(inputBuffer, quality = 80, maxWidth) {
  let pipeline = sharp(inputBuffer);
  if (maxWidth) {
    pipeline = pipeline.resize({ width: maxWidth, withoutEnlargement: true });
  }
  const outputBuffer = await pipeline.webp({ quality, effort: 4 }).toBuffer();
  const metadata = await sharp(outputBuffer).metadata();
  const base643 = outputBuffer.toString("base64");
  const dataUrl = `data:image/webp;base64,${base643}`;
  return {
    format: "webp",
    buffer: outputBuffer,
    width: metadata.width,
    height: metadata.height,
    size: outputBuffer.length,
    dataUrl
  };
}

